class Solution:
    def maxSum(self, nums: List[int], m: int, l: int, r: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        NEG = float('-inf')
        prev = [0] * (n + 1)
        cur = [NEG] * (n + 1)
        for _ in range(m):
            cur[0] = NEG
            for i in range(1, n + 1):
                cur[i] = cur[i - 1]
                for ln in range(l, r + 1):
                    t = i - ln
                    if t >= 0:
                        cur[i] = max(cur[i], prev[t] + P[i] - P[t])
            prev, cur = cur, [NEG] * (n + 1)
        return prev[n]

