from collections import deque
class Solution:
    def maxSum(self, nums: List[int], m: int, l: int, r: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        NEG = float('-inf')
        prev = [0] * (n + 1)
        cur = [NEG] * (n + 1)
        for _ in range(m):
            cur[0] = NEG
            dq = deque()
            for i in range(1, n + 1):
                t = i - l
                if t >= 0:
                    v = prev[t] - P[t]
                    while dq and dq[-1][1] <= v:
                        dq.pop()
                    dq.append((t, v))
                while dq and dq[0][0] < i - r:
                    dq.popleft()
                cur[i] = cur[i - 1]
                if dq:
                    cur[i] = max(cur[i], dq[0][1] + P[i])
            prev, cur = cur, [NEG] * (n + 1)
        return prev[n]

