class Solution {
public:
    long long maxSum(vector<int>& nums, int m, int l, int r) {
        int n = nums.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        const long long NEG = LLONG_MIN / 4;
        vector<long long> prev(n + 1, 0), cur(n + 1, NEG);
        for (int j = 0; j < m; j++) {
            cur[0] = NEG;
            deque<pair<int,long long>> dq;
            for (int i = 1; i <= n; i++) {
                int t = i - l;
                if (t >= 0) {
                    long long v = prev[t] - P[t];
                    while (!dq.empty() && dq.back().second <= v) dq.pop_back();
                    dq.push_back({t, v});
                }
                while (!dq.empty() && dq.front().first < i - r) dq.pop_front();
                cur[i] = cur[i - 1];
                if (!dq.empty()) cur[i] = max(cur[i], dq.front().second + P[i]);
            }
            swap(prev, cur);
            fill(cur.begin(), cur.end(), NEG);
        }
        return prev[n];
    }
};

