class Solution {
    public long maxSum(int[] nums, int m, int l, int r) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        final long NEG = Long.MIN_VALUE / 4;
        long[] prev = new long[n + 1], cur = new long[n + 1];
        Arrays.fill(cur, NEG);
        for (int j = 0; j < m; j++) {
            cur[0] = NEG;
            ArrayDeque<long[]> dq = new ArrayDeque<>();
            for (int i = 1; i <= n; i++) {
                int t = i - l;
                if (t >= 0) {
                    long v = prev[t] - P[t];
                    while (!dq.isEmpty() && dq.peekLast()[1] <= v) dq.pollLast();
                    dq.addLast(new long[]{t, v});
                }
                while (!dq.isEmpty() && dq.peekFirst()[0] < i - r) dq.pollFirst();
                cur[i] = cur[i - 1];
                if (!dq.isEmpty()) cur[i] = Math.max(cur[i], dq.peekFirst()[1] + P[i]);
            }
            long[] tmp = prev; prev = cur; cur = tmp;
            Arrays.fill(cur, NEG);
        }
        return prev[n];
    }
}

