    const NEG = -Infinity;
    let prev = new Array(n + 1).fill(0), cur = new Array(n + 1).fill(NEG);
    for (let j = 0; j < m; j++) {
        cur[0] = NEG;
        const dq = [];
        let head = 0;
        for (let i = 1; i <= n; i++) {
            const t = i - l;
            if (t >= 0) {
                const v = prev[t] - P[t];
                while (dq.length > head && dq[dq.length - 1][1] <= v) dq.pop();
                dq.push([t, v]);
            }
            while (dq.length > head && dq[head][0] < i - r) head++;
            cur[i] = cur[i - 1];
            if (dq.length > head) cur[i] = Math.max(cur[i], dq[head][1] + P[i]);
        }
        [prev, cur] = [cur, prev];
        cur.fill(NEG);
    }
    return prev[n];
};
